+    const result = run([file]);
+    assert.equal(result.status, 0);
+    assert.equal(result.stderr, '');
+    assert.equal(result.stdout, JSON.stringify(packContext(sections, 100)) + '\n');
+    failure(run([]));
+    failure(run([file, file]));
+    failure(run([join(directory, 'missing')]));
+    for (const contents of ['{', 'null', '[]', '{}',
+      JSON.stringify({ sections, maxBytes: 0 }),
+      JSON.stringify({ sections: [section('bad', '', -1)], maxBytes: 0 })]) {
+      writeFileSync(file, contents);
+      failure(run([file]));
+    }
+    const imported = spawnSync(process.execPath, ['--input-type=module', '-e',
+      `import ${JSON.stringify(new URL('../context-packet.js', import.meta.url).href)}`],
+    { encoding: 'utf8' });
+    assert.equal(imported.status, 0);
+    assert.equal(imported.stdout, '');
+    assert.equal(imported.stderr, '');
+  } finally {
+    rmSync(directory, { recursive: true, force: true });
+  }
+});

